#pragma once
#include <Arduino.h>

// Single-page joystick. Sends /d?x=..&y=.. every 100 ms, never stacks requests.
static const char INDEX_HTML[] PROGMEM = R"HTML(<!DOCTYPE html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">
<title>Rover</title>
<style>
body{margin:0;background:#111;color:#eee;font-family:sans-serif;text-align:center;user-select:none;-webkit-user-select:none}
#pad{width:280px;height:280px;margin:24px auto;border-radius:50%;background:#222;border:2px solid #555;position:relative;touch-action:none}
#knob{width:90px;height:90px;border-radius:50%;background:#3a8;position:absolute;left:95px;top:95px;pointer-events:none}
#st{font-size:20px;margin-top:14px}
.bad{color:#f55}
</style></head><body>
<div id="st">connecting...</div>
<div id="pad"><div id="knob"></div></div>
<div>Drag to drive. Release to stop.</div>
<script>
var pad=document.getElementById('pad'),knob=document.getElementById('knob'),st=document.getElementById('st');
var x=0,y=0,busy=false,down=false,R=95;
function setKnob(dx,dy){knob.style.left=(95+dx)+'px';knob.style.top=(95+dy)+'px';}
function move(e){
  var r=pad.getBoundingClientRect();
  var dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);
  var m=Math.sqrt(dx*dx+dy*dy);
  if(m>R){dx=dx*R/m;dy=dy*R/m;}
  setKnob(dx,dy);
  x=Math.round(dx*100/R);y=Math.round(-dy*100/R);
}
function release(){down=false;x=0;y=0;setKnob(0,0);}
pad.addEventListener('pointerdown',function(e){down=true;pad.setPointerCapture(e.pointerId);move(e);});
pad.addEventListener('pointermove',function(e){if(down)move(e);});
pad.addEventListener('pointerup',release);
pad.addEventListener('pointercancel',release);
document.addEventListener('visibilitychange',function(){if(document.hidden)release();});
window.addEventListener('blur',release);
setInterval(function(){
  if(busy||document.hidden)return;
  busy=true;
  var c=new AbortController();
  var t=setTimeout(function(){c.abort();},400);
  fetch('/d?x='+x+'&y='+y,{signal:c.signal,cache:'no-store'})
   .then(function(r){return r.json();})
   .then(function(j){
     var msg=j.v.toFixed(2)+' V';
     if(j.s=='low')msg+=' - battery low';
     if(j.s=='cut')msg+=' - battery empty, motors locked';
     st.textContent=msg;st.className=(j.s=='ok')?'':'bad';
   })
   .catch(function(){st.textContent='no link';st.className='bad';})
   .finally(function(){clearTimeout(t);busy=false;});
},100);
</script></body></html>
)HTML";

// Desktop 2WD phone-controlled rover - ESP32-C3-DevKitM-1 + DRV8833
// Phone joins the rover's Wi-Fi AP and drives from a web joystick.

#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include "pins.h"
#include "config.h"
#include "webpage.h"

// ---------- shared state (single 32-bit-or-smaller writes are atomic on RISC-V) ----------
static volatile int16_t  g_targetL = 0;        // -100..100 %
static volatile int16_t  g_targetR = 0;
static volatile uint32_t g_lastCmdMs = 0;
static volatile bool     g_haveCmd = false;
static volatile bool     g_battLockout = true; // start locked until the pack is measured
static volatile bool     g_battLow = false;
static volatile uint32_t g_vbatMv = 0;

static WebServer server(80);

// ---------- PWM wrapper: works with Arduino-ESP32 core 2.x and 3.x ----------
static const uint8_t PWM_PINS[4] = {PIN_AIN1, PIN_AIN2, PIN_BIN1, PIN_BIN2};
enum { CH_AIN1 = 0, CH_AIN2, CH_BIN1, CH_BIN2 };

static void pwmBegin() {
  for (uint8_t i = 0; i < 4; i++) {
    // Hold the line low before the PWM peripheral takes over.
    pinMode(PWM_PINS[i], OUTPUT);
    digitalWrite(PWM_PINS[i], LOW);
#if ESP_ARDUINO_VERSION_MAJOR >= 3
    ledcAttach(PWM_PINS[i], PWM_FREQ_HZ, PWM_BITS);
    ledcWrite(PWM_PINS[i], 0);
#else
    ledcSetup(i, PWM_FREQ_HZ, PWM_BITS);
    ledcAttachPin(PWM_PINS[i], i);
    ledcWrite(i, 0);
#endif
  }
}

static inline void pwmWrite(uint8_t ch, uint16_t duty) {
  if (duty > DUTY_MAX) duty = DUTY_MAX;   // hard cap, whatever the caller asks
#if ESP_ARDUINO_VERSION_MAJOR >= 3
  ledcWrite(PWM_PINS[ch], duty);
#else
  ledcWrite(ch, duty);
#endif
}

// ---------- motors ----------
static uint16_t speedToDuty(int pct) {
  int a = abs(pct);
  if (a < CMD_DEADBAND) return 0;
  if (a > 100) a = 100;
  return (uint16_t)map(a, CMD_DEADBAND, 100, DUTY_MIN, DUTY_MAX);
}

// Fast-decay drive: one input PWM, the other low. Both low = coast.
static void driveMotor(uint8_t chFwd, uint8_t chRev, int pct, bool invert) {
  if (invert) pct = -pct;
  uint16_t duty = speedToDuty(pct);
  if (pct > 0)      { pwmWrite(chRev, 0); pwmWrite(chFwd, duty); }
  else if (pct < 0) { pwmWrite(chFwd, 0); pwmWrite(chRev, duty); }
  else              { pwmWrite(chFwd, 0); pwmWrite(chRev, 0); }
}

static void motorsOff() {
  for (uint8_t i = 0; i < 4; i++) pwmWrite(i, 0);
}

static int slew(int cur, int tgt) {
  bool slowing = (tgt == 0) || (cur != 0 && ((cur > 0) != (tgt > 0))) || (abs(tgt) < abs(cur));
  int step = slowing ? DECEL_STEP : ACCEL_STEP;
  if (tgt > cur) return min(cur + step, tgt);
  return max(cur - step, tgt);
}

// Runs on its own task so a slow HTTP client can never delay the failsafe.
static void controlTask(void *) {
  int curL = 0, curR = 0;
  bool awake = false;
  TickType_t last = xTaskGetTickCount();
  for (;;) {
    vTaskDelayUntil(&last, pdMS_TO_TICKS(CONTROL_PERIOD_MS));

    // Read the stamp before the clock, so a command landing in between
    // cannot make the age wrap around to a huge number.
    uint32_t stamp = g_lastCmdMs;
    uint32_t now = millis();
    bool fresh = g_haveCmd && (uint32_t)(now - stamp) < CMD_TIMEOUT_MS;
    bool allow = fresh && !g_battLockout;

    if (!allow) {
      curL = curR = 0;
      motorsOff();
      digitalWrite(PIN_NSLEEP, LOW);
      awake = false;
      continue;
    }

    if (!awake) {
      // DRV8833 needs about 1 ms to wake; give it one whole tick with PWM at zero.
      motorsOff();
      digitalWrite(PIN_NSLEEP, HIGH);
      awake = true;
      continue;
    }

    curL = slew(curL, g_targetL);
    curR = slew(curR, g_targetR);
    driveMotor(CH_AIN1, CH_AIN2, curL, INVERT_LEFT);
    driveMotor(CH_BIN1, CH_BIN2, curR, INVERT_RIGHT);
  }
}

// ---------- battery ----------
static uint32_t readVbatRawMv() {
  uint32_t pinMv = analogReadMilliVolts(PIN_VBAT_SENSE);
  uint32_t mv = pinMv * (DIV_R_TOP_K + DIV_R_BOTTOM_K) / DIV_R_BOTTOM_K;
  return mv * VBAT_CAL_PERMILLE / 1000;
}

static uint32_t s_vbatFiltX16 = 0;   // IIR state, mV * 16

static void batteryBegin() {
  analogSetPinAttenuation(PIN_VBAT_SENSE, ADC_11db);  // 2.08 V at the pin needs the widest range
  uint32_t sum = 0;
  for (int i = 0; i < 8; i++) { sum += readVbatRawMv(); delay(2); }
  uint32_t mv = sum / 8;
  s_vbatFiltX16 = mv * 16;
  g_vbatMv = mv;
  g_battLockout = (mv < VBAT_CUTOFF_MV);   // empty or missing pack: never enable motors
  g_battLow = (mv < VBAT_WARN_MV);
}

static void batteryUpdate(uint32_t now) {
  static uint32_t lastSample = 0;
  static uint32_t belowSince = 0;
  static bool below = false;
  if (now - lastSample < VBAT_SAMPLE_MS) return;
  lastSample = now;

  s_vbatFiltX16 = s_vbatFiltX16 - (s_vbatFiltX16 / 16) + readVbatRawMv();
  uint32_t mv = s_vbatFiltX16 / 16;
  g_vbatMv = mv;

  if (mv < VBAT_CUTOFF_MV) {
    if (!below) { below = true; belowSince = now; }
    if (now - belowSince >= VBAT_CUTOFF_HOLD_MS) g_battLockout = true;
  } else {
    below = false;
  }

  if (mv < VBAT_WARN_MV) g_battLow = true;
  if (mv >= VBAT_RECOVER_MV) { g_battLow = false; g_battLockout = false; }
}

// ---------- status LED ----------
static void ledUpdate(uint32_t now) {
  bool blink = ((now / 500) % 2) == 0;
  uint32_t stamp = g_lastCmdMs;
  bool linked = g_haveCmd && (uint32_t)(millis() - stamp) < 1000;
  bool red, green;
  if (g_battLockout)   { red = true;  green = false; }          // solid red: motors locked
  else if (g_battLow)  { red = blink; green = false; }          // flashing red: charge soon
  else                 { red = false; green = linked ? true : blink; }
  digitalWrite(PIN_LED_RED, red ? HIGH : LOW);
  digitalWrite(PIN_LED_GREEN, green ? HIGH : LOW);
}

// ---------- web ----------
static void handleRoot() {
  server.sendHeader("Cache-Control", "no-store");
  server.send_P(200, "text/html", INDEX_HTML);
}

static void handleDrive() {
  int x = constrain(server.arg("x").toInt(), -100, 100);   // turn, right positive
  int y = constrain(server.arg("y").toInt(), -100, 100);   // throttle, forward positive
  int turn = x * TURN_GAIN_PCT / 100;
  int l = constrain(y + turn, -100, 100);
  int r = constrain(y - turn, -100, 100);
  g_targetL = (int16_t)l;
  g_targetR = (int16_t)r;
  g_lastCmdMs = millis();
  g_haveCmd = true;

  const char *s = g_battLockout ? "cut" : (g_battLow ? "low" : "ok");
  uint32_t mv = g_vbatMv;
  char buf[48];
  snprintf(buf, sizeof(buf), "{\"v\":%lu.%02lu,\"s\":\"%s\"}",
           (unsigned long)(mv / 1000), (unsigned long)((mv % 1000) / 10), s);
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json", buf);
}

static void handleNotFound() {
  server.send(404, "text/plain", "not found");
}

// ---------- setup / loop ----------
void setup() {
  // Driver asleep and inputs low before anything else can go wrong.
  pinMode(PIN_NSLEEP, OUTPUT);
  digitalWrite(PIN_NSLEEP, LOW);
  pwmBegin();

  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  digitalWrite(PIN_LED_GREEN, LOW);
  digitalWrite(PIN_LED_RED, LOW);

  Serial.begin(115200);
  Serial.println();
  Serial.println("Rover booting");

  batteryBegin();
  Serial.printf("VBAT %lu mV%s\n", (unsigned long)g_vbatMv,
                g_battLockout ? " (below cut-off, motors locked)" : "");

  WiFi.mode(WIFI_AP);
  uint8_t mac[6];
  WiFi.softAPmacAddress(mac);
  char ssid[24];
  snprintf(ssid, sizeof(ssid), "%s%02X%02X", AP_SSID_PREFIX, mac[4], mac[5]);
  WiFi.softAP(ssid, AP_PASSWORD, AP_CHANNEL, 0, AP_MAX_CLIENTS);
  Serial.printf("AP \"%s\" up, open http://%s/\n", ssid, WiFi.softAPIP().toString().c_str());

  server.on("/", HTTP_GET, handleRoot);
  server.on("/d", HTTP_GET, handleDrive);
  server.onNotFound(handleNotFound);
  server.begin();

  // Higher priority than the Arduino loop task (priority 1).
  xTaskCreate(controlTask, "control", 3072, nullptr, 3, nullptr);
}

void loop() {
  uint32_t now = millis();
  server.handleClient();
  batteryUpdate(now);
  ledUpdate(now);

  static uint32_t lastLog = 0;
  if (now - lastLog >= 2000) {
    lastLog = now;
    Serial.printf("VBAT %lu mV  low=%d lock=%d  clients=%d  tgt L=%d R=%d\n",
                  (unsigned long)g_vbatMv, (int)g_battLow, (int)g_battLockout,
                  WiFi.softAPgetStationNum(), (int)g_targetL, (int)g_targetR);
  }
  delay(2);   // lets Wi-Fi and idle tasks run
}
